<script lang="ts">
 import {request} from '#lib/client/api.ts';import {uploadOriginal} from '#lib/client/uploads.ts';import type {Row} from '#lib/client/types.ts';
 let {onready}:{onready:(document:Row)=>void}=$props();let file:File|null=$state(null),document:Row|null=$state(null),busy=$state(false),error=$state('');
 async function upload(){if(!file||busy)return;busy=true;error='';try{document=await uploadOriginal(file);if(document?.status==='available')onready(document);}catch(cause){error=cause instanceof Error?cause.message:'Original konnte nicht hochgeladen werden. Die Rechnungsangaben bleiben erhalten.';}finally{busy=false;}}
 async function check(){if(!document||busy)return;busy=true;error='';try{const choices=await request('/api/v1/lookups/documents?include_id='+document.id,undefined,'GET');const ready=choices.find((choice:Row)=>choice.id===document?.id);if(ready){document={...document,status:'available'};onready({...document,name:ready.name});}}catch(cause){error=(cause as Error).message;}finally{busy=false;}}
</script>
<div class="inline-original"><p class="field-help">Original direkt hochladen. Die Rechnung bleibt geöffnet; auswählbar wird die Datei erst nach der Sicherheitsprüfung.</p>{#if error}<p class="field-error" role="alert">{error}</p>{/if}{#if document}<p class="small mt"><strong>{document.name}</strong> · {document.status==='available'?'Geprüft und als Original ausgewählt':'Hochgeladen · Sicherheitsprüfung offen'}</p>{#if document.status!=='available'}<button type="button" class="btn small mt" disabled={busy} onclick={check}>{busy?'Wird geprüft …':'Prüfstatus aktualisieren'}</button>{/if}{:else}<input type="file" aria-label="Rechnungsoriginal auswählen" accept=".pdf,.xml,.png,.jpg,.jpeg,.tif,.tiff" onchange={e=>file=e.currentTarget.files?.[0]??null}/><button type="button" class="btn small" disabled={busy||!file} onclick={upload}>{busy?'Wird hochgeladen …':'Original hochladen'}</button>{/if}</div>
<style>.inline-original{grid-column:1/-1;border:1px solid var(--line);border-radius:10px;padding:14px;background:var(--wash)}input{font-size:12px;max-width:100%;margin-top:12px}button{margin-top:10px}</style>
